namespace Gordic.Ada.WebClient {
    var gcontent = Decorators.gcontent;

    @gcontent
    export class GAkceNavazane extends GContentBase {

        private modeluct: Gordic.Ada.Interface.GSrvscisDto[];
        private datauct: Gordic.Ada.Interface.GSrvscisDto[];
        private row: Gordic.Ada.Interface.GSrvscisDto | null = null;
        private typ_akce_sum: Gordic.Ada.Interface.TypAkceSumEnum;

//        private globals = Gordic.Ada.Globals.GAdaGlobals;
        private readonly globals: Gordic.Ada.WebClient.DTO.GAdaGlobalsDto;

        private view_ISL: Gordic.Isl.View<Gordic.Ada.Interface.GSrvscisDto>;
        private filter_akce: Gordic.Ada.Interface.GAgDokladyFilterDto;

        private gridFormatSeznam: Gordic.Data.GridFormat<Gordic.Ada.Interface.GSrvscisDto>;

        onContentReady() {

            var that = this;
            var $tab = $(this.contentDiv);
            var datauct = this.modeluct;

            $tab.empty();

            var cnt = this;

            var mainForm = $("<div>").appendTo(this.element).gform("setup", { layoutDescriptor: "L1M1S1 LMS-0-12-0" }).gformsection("create");

            this.actions.addRange({
            //    actNew: {
            //        caption: "Nový", icon: "gi-plus",
            //        enabled: (that.globals.Param_Akce_Editace_TP!),
            //        run: () => {
            //            return that.detail_radku(true, true);
            //        }
            //    },
                actDetail: {
                    icon: "gi-detail",
                    caption: "Detail",
                    primary: true,
                    run: () => {
                        return that.detail_radku_tab();
                    }
                },
                actDelete: {
                    caption: that.globals.BAR_Typ_Inst == Interface.SrvTypIntalaceEnum.MO ? "Oddělit PP" : "Oddělit akci",
                    icon: "fa-trash",
                    enabled: ((that.globals.Param_Akce_Editace_TP!) && ((this.typ_akce_sum === Gordic.Ada.Interface.TypAkceSumEnum.Obalkova) || (this.typ_akce_sum === Gordic.Ada.Interface.TypAkceSumEnum.Souhrnna))),
                    visible: ((that.globals.Param_Akce_Editace_TP!) && ((this.typ_akce_sum === Gordic.Ada.Interface.TypAkceSumEnum.Obalkova) || (this.typ_akce_sum === Gordic.Ada.Interface.TypAkceSumEnum.Souhrnna))),
                    run: () => {
                        return that.smazani_radku();
                    }
                },
            });

            //nastavení menuBaru
            //this.menuBar(this.actions.createBar(["actNew*", "actDetail*", "actDelete*"]));
            this.menuBar(this.actions.createBar(["actDetail*", "actDelete*"]));

            //var actEdit = new GAction({
            //    name: "dblclick",
            //    run: function (ev, ctx) {
            //        GDlg.alert("Dvojklik");
            //        // ctx.cellInfo.data
            //    }
            //});


            this.gridFormatSeznam = new Gordic.Data.GridFormat()
                .addIconColumn({
                    name: "aktivita",
                    field: "aktivita",
                    caption: "Stav vazby",
                    // width: 25,
                    formatPreset: Gordic.Global.Enums.GridColumnFormatIcon.icon,
                    iconTemplate: function (data) {
                        switch (data.aktivita) {
                            case 100: return { icon: "fa-check-circle-o g-state-success g-state-text", text: "Aktivní", caption: "Aktivní", tooltip: "Aktivní" };
                            case 300: return { icon: "fa-check-circle g-state-warning g-state-text", text: "Návrh", caption: "Návrh", tooltip: "Návrh" };
                            case 500: return { icon: "fa-trash g-state-error g-state-text", text: "Neaktivní", caption: "Neaktivní", tooltip: "Neaktivní" };
                            default: return null;
                        }
                    }
                })
                .addIconColumn({
                    name: "aktivita_cislo_old",
                    field: "aktivita_cislo_old",
                    caption: "Stav PP",
                    // width: 25,
                    formatPreset: Gordic.Global.Enums.GridColumnFormatIcon.icon,
                    iconTemplate: function (data) {
                        switch (data.aktivita_cislo_old) {
                            case 100: return { icon: "fa-check-circle-o g-state-success g-state-text", text: "Aktivní", caption: "Aktivní", tooltip: "Aktivní" };
                            case 300: return { icon: "fa-check-circle g-state-warning g-state-text", text: "Návrh", caption: "Návrh", tooltip: "Návrh" };
                            case 500: return { icon: "fa-trash g-state-error g-state-text", text: "Neaktivní", caption: "Neaktivní", tooltip: "Neaktivní" };
                            default: return null;
                        }
                    }
                })
                .addNumberColumn({
                    name: "rok_od",
                    caption: "Rok",
                    width: 50,
                });

            if ((this.typ_akce_sum === Gordic.Ada.Interface.TypAkceSumEnum.Obalkova) || (this.typ_akce_sum === Gordic.Ada.Interface.TypAkceSumEnum.Souhrnna)) {
                this.gridFormatSeznam
                    .addTextColumn({
                        name: "cislo_old",
                        caption: that.globals.BAR_Typ_Inst == Interface.SrvTypIntalaceEnum.MO ? "Číslo PP navázané" : "Číslo akce navázané",
                        width: 150
                    });
            }
            else
            {
                this.gridFormatSeznam
                    .addTextColumn({
                        name: "cislo",
                        caption: that.globals.BAR_Typ_Inst == Interface.SrvTypIntalaceEnum.MO ? "Číslo PP nadřazané" : "Číslo akce nadřazané",
                        width: 150
                    });
            }

            this.gridFormatSeznam
                .addDateTimeColumn({
                    name: "dat_zmena",
                    caption: "Datum změny",
                    customClass: "dt-left",
                    width: 140,
                })
                .addTextColumn({
                    name: "zmenu_prov_txt",
                    caption: "Změnu provedl",
                    width: 400
                });

            var $mainTable = $("<div>")
                //.css("height", "100%")
                .appendTo(mainForm)
                .gautofit()
                .ggrid({
                    columnMode: "full",

                    selection(ev, ctx) {
                        that.row = $mainTable.ggrid("activeRow");
                        if (that.row !== null) {
                        }
                    },

                    defaultAction: new GAction({
                        name: "gridRowSelectedAct",
                        run(ev, ctx) {
                            that.row = ctx.cellInfo.data;    //data, ze kterych byl vytvoren radek
                            return that.detail_radku_tab();
                        }
                    }),

                    searchColumns: ["*cislo", "*cislo_old"],

                    columns: this.gridFormatSeznam 
                });

            if ((this.typ_akce_sum === Gordic.Ada.Interface.TypAkceSumEnum.Obalkova) || (this.typ_akce_sum === Gordic.Ada.Interface.TypAkceSumEnum.Souhrnna)) {
                that.view_ISL = new Gordic.Isl.View(this.isl.AkceSouvisejici.list_Navazane({ filters: this.filter_akce }));
            }
            else {
                that.view_ISL = new Gordic.Isl.View(this.isl.AkceSouvisejici.list_Navazane_Nad({ filters: this.filter_akce }));
            }

            $mainTable.ggrid("setData", that.view_ISL);

        }

        smazani_radku() {
            var that = this;

            // souhrnna - sdruzenim se deaktivuji sdruzovane akce, tak je mohu pri ozvazovani aktivovat
            if (this.typ_akce_sum === Gordic.Ada.Interface.TypAkceSumEnum.Souhrnna) {
                if ((that.row != undefined) && (that.row != null)) {
                    that.dialogs.messageBox("Dotaz", that.globals.BAR_Typ_Inst == Interface.SrvTypIntalaceEnum.MO ? "Opravdu oddělit PP?" : "Opravdu oddělit akci?", Gordic.Ada.WebClient.AdaConst.mbbYesNoNegativ, GDlg.mbiQuestion)
                        .on("yes", function () {
                            that.isl.AkceSouvisejici.read({ data: that.row! })
                                .getData()
                                .done(function (new_data2) {
                                    that.isl.AkceSouvisejici.oddelit({ data: new_data2 })
                                        .get()
                                        .then(function (response) {
                                            that.dialogs.messageBox("Dotaz", "Aktivovat odpojovanou PP?", Gordic.Ada.WebClient.AdaConst.mbbYesNoNegativ, GDlg.mbiQuestion)
                                                .on("yes", function () {
                                                    var aktivovana_akce: Interface.GAkceDto = {};
                                                    aktivovana_akce.rok = new_data2.rok_od;
                                                    aktivovana_akce.ico = new_data2.ico;
                                                    aktivovana_akce.cislo = new_data2.cislo_old;
                                                    aktivovana_akce.ixs_cia = "";

                                                    that.isl.Akce.read({ data: aktivovana_akce })
                                                        .get()
                                                        .then(function (response2) {
                                                            // a budu aktivivat 
                                                            aktivovana_akce = response2.data;
                                                            aktivovana_akce.aktivita = (that.globals.Param_Akce_AutSchv == Interface.TypAutomatSchvaleniNovaAkceEnum.Ano ) ? Interface.AktivitaAkceEnum.Aktivni : Interface.AktivitaAkceEnum.Navrh;
                                                            aktivovana_akce.typ_akce_sum = Interface.TypAkceSumEnum.Samostatna;

                                                            that.isl.Akce.update({ data: aktivovana_akce })
                                                                .get()
                                                                .then(function (response3) {
                                                                    that.element.trigger("ada_saveNavaz", [{ data: response3.data }]);
                                                                    that.view_ISL.requestData({}, {
                                                                        onResponse: function (response4) {
                                                                            var new_data = TypeGuards.hasProperty(response4, "data") ? response4.data : [];

                                                                            that.element.trigger("ada_saveNavazPocet", [{ pocet: new_data.length }]);

                                                                            if (new_data.length == 0) {
                                                                                that.dialogs.messageBox("Dotaz", "Na Souhrnnou PP není navázána žádná další PP. Nastavit typ na Samostatná?", Gordic.Ada.WebClient.AdaConst.mbbYesNoNegativ, GDlg.mbiQuestion)
                                                                                    .on("yes", function () {

                                                                                        aktivovana_akce.cislo = new_data2.cislo;
                                                                                        aktivovana_akce.ixs_cia = "";

                                                                                        that.isl.Akce.read({ data: aktivovana_akce })
                                                                                            .get()
                                                                                            .then(function (response5) {
                                                                                                // a budu aktivivat 
                                                                                                aktivovana_akce = response5.data;
                                                                                                aktivovana_akce.typ_akce_sum = Interface.TypAkceSumEnum.Samostatna;
                                                                                                that.isl.Akce.update({ data: aktivovana_akce })
                                                                                                    .get()
                                                                                                    .then(function (response6) {
                                                                                                        that.element.trigger("ada_saveNavaz_akt", [{ data: response6.data }]);
                                                                                                    });
                                                                                            })
                                                                                    });
                                                                            }
                                                                            return response4;
                                                                        }
                                                                    });
                                                                })
                                                                .fail(function () {
                                                                });
                                                        })
                                                        .fail(function () {
                                                        });
                                                })
                                                .on("no", function () {
                                                    //that.view_ISL.requestData({});

                                                    var aktivovana_akce: Interface.GAkceDto = {};
                                                    aktivovana_akce.rok = new_data2.rok_od;
                                                    aktivovana_akce.ico = new_data2.ico;
                                                    aktivovana_akce.cislo = new_data2.cislo_old;
                                                    aktivovana_akce.ixs_cia = "";

                                                    that.isl.Akce.read({ data: aktivovana_akce })
                                                        .get()
                                                        .then(function (response2) {
                                                            // a budu aktivivat 
                                                            aktivovana_akce = response2.data;
                                                            //aktivovana_akce.aktivita = Interface.AktivitaAkceEnum.Aktivni;
                                                            aktivovana_akce.typ_akce_sum = Interface.TypAkceSumEnum.Samostatna;

                                                            that.isl.Akce.update({ data: aktivovana_akce })
                                                                .get()
                                                                .then(function (response3) {
                                                                    that.element.trigger("ada_saveNavaz", [{ data: response3.data }]);
                                                                    that.view_ISL.requestData({}, {
                                                                        onResponse: function (response4) {
                                                                            var new_data = TypeGuards.hasProperty(response4, "data") ? response4.data : [];

                                                                            that.element.trigger("ada_saveNavazPocet", [{ pocet: new_data.length }]);

                                                                            if (new_data.length == 0) {
                                                                                that.dialogs.messageBox("Dotaz", "Na Souhrnnou PP není navázána žádná další PP. Nastavit typ na Samostatná?", Gordic.Ada.WebClient.AdaConst.mbbYesNoNegativ, GDlg.mbiQuestion)
                                                                                    .on("yes", function () {

                                                                                        aktivovana_akce.cislo = new_data2.cislo;
                                                                                        aktivovana_akce.ixs_cia = "";

                                                                                        that.isl.Akce.read({ data: aktivovana_akce })
                                                                                            .get()
                                                                                            .then(function (response5) {
                                                                                                // a budu aktivivat 
                                                                                                aktivovana_akce = response5.data;
                                                                                                aktivovana_akce.typ_akce_sum = Interface.TypAkceSumEnum.Samostatna;
                                                                                                that.isl.Akce.update({ data: aktivovana_akce })
                                                                                                    .get()
                                                                                                    .then(function (response6) {
                                                                                                        that.element.trigger("ada_saveNavaz_akt", [{ data: response6.data }]);
                                                                                                    });
                                                                                            })
                                                                                    });
                                                                            }
                                                                            return response4;
                                                                        }
                                                                    });
                                                                })
                                                                .fail(function () {
                                                                });
                                                        })
                                                        .fail(function () {
                                                        });

                                                });

                                            //that.view_ISL.updateData(response.data, "update");
                                            //that.newOps({ title: "Rozpis zdrojů ({0})".replace("{0}", that.view_ISL.getCount().toString()) });
                                        })
                                        .fail(function () {
                                        });
                                });
                        })
                }
            }

            // obalkova - seskupenim se pouze provazou seskupovae akce, tak se zdna aktivace neprovadi
            if (this.typ_akce_sum === Gordic.Ada.Interface.TypAkceSumEnum.Obalkova) {
                if ((that.row != undefined) && (that.row != null)) {
                    that.dialogs.messageBox("Dotaz", that.globals.BAR_Typ_Inst == Interface.SrvTypIntalaceEnum.MO ? "Opravdu oddělit PP?" : "Opravdu oddělit akci?", Gordic.Ada.WebClient.AdaConst.mbbYesNoNegativ, GDlg.mbiQuestion)
                        .on("yes", function () {
                            that.isl.AkceSouvisejici.read({ data: that.row! })
                                .getData()
                                .done(function (new_data2) {
                                    that.isl.AkceSouvisejici.delete({ data: new_data2 })
                                        .get()
                                        .then(function (response) {

                                            var aktivovana_akce: Interface.GAkceDto = {};
                                            aktivovana_akce.rok = new_data2.rok_od;
                                            aktivovana_akce.ico = new_data2.ico;
                                            aktivovana_akce.cislo = new_data2.cislo_old;
                                            aktivovana_akce.ixs_cia = "";

                                            that.isl.Akce.read({ data: aktivovana_akce })
                                                .get()
                                                .then(function (response2) {
                                                    // a budu aktivivat 
                                                    aktivovana_akce = response2.data;
                                                    aktivovana_akce.typ_akce_sum = Interface.TypAkceSumEnum.Samostatna;

                                                    that.isl.Akce.update({ data: aktivovana_akce })
                                                        .get()
                                                        .then(function (response3) {
                                                            that.element.trigger("ada_saveNavaz", [{ data: response3.data }]);
                                                            that.view_ISL.requestData({}, {
                                                                onResponse: function (response4) {
                                                                    var new_data = TypeGuards.hasProperty(response4, "data") ? response4.data : [];

                                                                    that.element.trigger("ada_saveNavazPocet", [{ pocet: new_data.length }]);

                                                                    if (new_data.length == 0) {
                                                                        that.dialogs.messageBox("Dotaz", "Na Obálkovou PP není navázána žádná další PP. Nastavit typ na Samostatná?", Gordic.Ada.WebClient.AdaConst.mbbYesNoNegativ, GDlg.mbiQuestion)
                                                                            .on("yes", function () {

                                                                                aktivovana_akce.cislo = new_data2.cislo;
                                                                                aktivovana_akce.ixs_cia = "";

                                                                                that.isl.Akce.read({ data: aktivovana_akce })
                                                                                    .get()
                                                                                    .then(function (response5) {
                                                                                        // a budu aktivivat 
                                                                                        aktivovana_akce = response5.data;
                                                                                        aktivovana_akce.typ_akce_sum = Interface.TypAkceSumEnum.Samostatna;
                                                                                        that.isl.Akce.update({ data: aktivovana_akce })
                                                                                            .get()
                                                                                            .then(function (response6) {
                                                                                                that.element.trigger("ada_saveNavaz_akt", [{ data: response6.data }]);
                                                                                            });
                                                                                    })
                                                                            });
                                                                    }
                                                                    return response4;
                                                                }
                                                            });
                                                        })
                                                        .fail(function () {
                                                        });
                                                })
                                                .fail(function () {
                                                });

                                        });
                                });
                        })
                }
            }
            
        }


        detail_radku_tab() {
            var that = this;
            var l_cislo = "";

            if ((that.row != undefined) && (that.row != null))
            {
                if ((this.typ_akce_sum === Gordic.Ada.Interface.TypAkceSumEnum.Obalkova) || (this.typ_akce_sum === Gordic.Ada.Interface.TypAkceSumEnum.Souhrnna))
                {
                    l_cislo = that.row.cislo_old!;
                }
                else
                {
                    l_cislo = that.row.cislo!;
                }

                // otevření nové záložky
                Gordic.WebApp.Utility.openApp(
                    {
                        ixx1: l_cislo, // id cílového objektu v nově otevírané záložce
                        ixx2: null,  // druhé id cílového objektu v případě složeného klíče (nepovinné)
                        ixx3: null,  // druhé id cílového objektu v případě složeného klíče (nepovinné)
                        typAg: 120,  // typ agendy cílového objektu (nepovinné)
                        faze: null,  // fáze požadovaná pro otevření cílového objektu (nepovinné)
                        banCurrentApp: false, // příznak zákazu použití aktuální fáze (nepovinné)
                        noAppFail: false  // příznak vyvolání výjimky při nenalezení cílové fáze (nepovinné) 
                    },
                    "OpenDetail"            // název metody spuštěné po otevření nové záložky
                );
            }
        }

    }
}

